  assert.equal(out.rounds, 3);
  assert.deepEqual(calls.filter((c) => c.opts.label?.startsWith('fix')).map((c) => c.opts.label), ['fix R1']);
  assert.match(calls.find((c) => c.opts.label === 'R3 A').prompt, /- F1 \[open\]/);
